fn check(name: []const u8, data: []const u8, bad: *usize) !void {
    const a = std.testing.allocator;
    const p = try gzip.compress(a, data);
    defer a.free(p);
    if (gzip.decompress(a, p, data.len)) |out| {
        defer a.free(out);
        if (!std.mem.eql(u8, out, data)) {
            bad.* += 1;
            std.debug.print("MISMATCH {s} len={d}\n", .{ name, data.len });
        }
    } else |e| {
        bad.* += 1;
        std.debug.print("REJECT {s} len={d}: {s}\n", .{ name, data.len, @errorName(e) });
    }
}

test "realistic" {
    const a = std.testing.allocator;
    var bad: usize = 0;
    var prng = std.Random.DefaultPrng.init(42);
    const r = prng.random();
    const sizes = [_]usize{ 1000, 8 << 10, 64 << 10, 1 << 20 };
    for (sizes) |n| {
        const buf = try a.alloc(u8, n);
        defer a.free(buf);
        for (0..8) |trial| {
            // PLAIN i64 timestamps with small random deltas
            {
                var t: i64 = 1_700_000_000_000 + @as(i64, @intCast(trial));
                var i: usize = 0;
                while (i + 8 <= n) : (i += 8) {
                    t += r.intRangeAtMost(i64, 0, 1000);
                    std.mem.writeInt(i64, buf[i..][0..8], t, .little);
                }
                try check("ts", buf[0 .. n & ~@as(usize, 7)], &bad);
            }
            // geometric byte distribution (skewed)
            {
                for (buf) |*b| {
                    var v: u8 = 0;
                    while (v < 255 and r.boolean()) v += 1;
                    b.* = v;
                }
                try check("geom", buf, &bad);
            }
            // PLAIN i32 small ints, zipf-ish
            {
                var i: usize = 0;
                while (i + 4 <= n) : (i += 4) {
                    const v: i32 = @intCast(@as(u32, 1) << @intCast(r.intRangeAtMost(u5, 0, 20)) | r.int(u4));
                    std.mem.writeInt(i32, buf[i..][0..4], v, .little);
                }
                try check("zipf32", buf[0 .. n & ~@as(usize, 3)], &bad);
            }
            // words text
            {
                const words = [_][]const u8{ "the ", "of ", "and ", "a ", "to ", "in ", "is ", "you ", "that ", "it ", "parquet ", "column ", "zebra ", "quixotic ", "Xylophone, ", "1234 ", "\n" };
                var i: usize = 0;
                while (i < n) {
                    // zipf: pick index with geometric
                    var k: usize = 0;
                    while (k + 1 < words.len and r.boolean()) k += 1;
                    for (words[k]) |c| {
                        if (i >= n) break;
                        buf[i] = c;
                        i += 1;
                    }
                }
                try check("text", buf, &bad);
            }
        }
    }
    std.debug.print("realistic: {d} bad\n", .{bad});
}

