//! Standalone repro: std.compress.flate.Decompress panics ("integer overflow" in peekBitsEnding)
//! on a truncated gzip stream in Zig 0.16.0; Zig 0.17.0 returns an error.
//! Run: zig test flate_repro.zig   (Debug or ReleaseSafe)
//!
//! Cause (0.16.0 lib/std/compress/flate/Decompress.zig): tossBitsShort checks
//!     if (d.input.bufferedLen() * 8 + d.consumed_bits < n) return error.EndOfStream;
//! ("+" instead of "-"), so near the end of input it tosses bits that peekBitsShortEnding
//! zero-padded. The toss consumes the last buffered byte and leaves consumed_bits != 0 with
//! nothing buffered; the next peekBitsEnding computes `left.len * 8 - d.consumed_bits` = 0 - k.
//! 0.17.0 fixed the sign (and added the test "truncated input ending when reading dynamic
//! length bits").
const std = @import("std");

test "truncated gzip stream returns an error instead of panicking" {
    var bytes: [47]u8 = undefined;
    _ = try std.fmt.hexToBytes(&bytes, "1f8b08000000000000ffedd1db9182300046e156fe021c07506e7dd0006824b240204b00a97e67e7f4e013057c2fe7");
    var in: std.Io.Reader = .fixed(&bytes);
    var out: std.Io.Writer.Allocating = .init(std.testing.allocator);
    defer out.deinit();
    var d: std.compress.flate.Decompress = .init(&in, .gzip, &.{});
    try std.testing.expectError(error.ReadFailed, d.reader.streamRemaining(&out.writer));
}

